FT area = FT(0);
if (polygon.size() < 3) return area;
const Point_2& p0 = polygon[0];
for (std::size_t i = 1; i < polygon.size() - 1; ++i) {
    const Point_2& p1 = polygon[i];
    const Point_2& p2 = polygon[i + 1];
    area += CGAL::cross_product(p1 - p0, p2 - p0);
}
return area / FT(2);

